  const [queueClock, setQueueClock] = useState(() => Date.now());
  const nativeNetworkState = Network.useNetworkState();
  const [networkStatus, setNetworkStatus] = useState<"online" | "offline" | "unknown">(Platform.OS === "web" && typeof window !== "undefined" ? window.navigator.onLine === false ? "offline" : "online" : "unknown");
  const [storageStatus, setStorageStatus] = useState<"checking" | "available" | "restricted">("checking");
  const [showConnectionDetails, setShowConnectionDetails] = useState(false);
  const [automaticRetriesEnabled, setAutomaticRetriesEnabled] = useState(true);
  const [retrySettings, setRetrySettings] = useState<AiRetrySettings>(DEFAULT_AI_RETRY_SETTINGS);
  const [notificationSettings, setNotificationSettings] = useState<AiNotificationSettings>(DEFAULT_AI_NOTIFICATION_SETTINGS);
  const [queueActivity, setQueueActivity] = useState<QueueActivityEvent[]>([]);
